import pandas as pd
import numpy as np

try:
    from statsmodels.tsa.stattools import grangercausalitytests
    has_stats = True
except ImportError:
    has_stats = False

# Load rolling CSV (assume from v2.6)
df = pd.read_csv('storage/shared/agency_lab/analyses/csv/v2_6_granger.csv')

# Example for axiom
persistence = df[df['lineage'] == 'axiom']['persistence_rate'].values
collab = df[df['lineage'] == 'axiom']['collaboration_index'].values

if len(persistence) < 4 or len(collab) < 4:
    print("Error: Insufficient data length")
else:
    data = pd.DataFrame({'persistence': persistence, 'collab': collab})

    if has_stats:
        results = grangercausalitytests(data[['collab', 'persistence']], maxlag=2, verbose=False)
        for lag, res in results.items():
            print(f"Lag {lag}: p-value {res[0]['ssr_ftest'][1]:.3f}")
    else:
        corr = np.corrcoef(persistence, collab)[0,1]
        print(f"Fallback Correlation: {corr:.3f}")
